abstract class Animal {
    abstract void makeSound();
}

class Dog extends Animal {
    @Override void makeSound() { System.out.println("Woof!"); }
}

class Cat extends Animal {
    @Override void makeSound() { System.out.println("Meow!"); }
}

// Runtime Polymorphism
Animal pet = new Dog();
pet.makeSound(); // JVM invokevirtual reads Dog vtable[0] -> Woof!
pet = new Cat();
pet.makeSound(); // JVM invokevirtual reads Cat vtable[0] -> Meow!
